#include <iostream>

class GradeTracker {
public:
    // C++11 in-class member initializers
    unsigned int aCount = 0;
    unsigned int bCount = 0;
    unsigned int otherCount = 0;

    void recordGrade(char grade) {
        // Each case label must be an integral constant expression
        switch (grade) {
            case 'A':
            case 'a':
                ++aCount;
                break;
            case 'B':
            case 'b':
                ++bCount;
                break;
            default:
                ++otherCount;
                break;
        }
    }
};

int main() {
    GradeTracker tracker;
    char grades[] = {'A', 'b', 'A', 'x', 'a'};

    for (char g : grades) {
        tracker.recordGrade(g);
    }

    std::cout << "A count: " << tracker.aCount << "\n";
    std::cout << "B count: " << tracker.bCount << "\n";
    std::cout << "Other count: " << tracker.otherCount << "\n";
    return 0;
}

#include <iostream>

int main() {
    // Demonstrating break in a for loop
    unsigned int count;
    for (count = 1; count <= 10; ++count) {
        if (count == 5) {
            break; // terminates loop when count reaches 5
        }
        std::cout << count << " ";
    }
    std::cout << "\nBroke out of loop at count = " << count << "\n";

    // Demonstrating continue with logical AND (&&)
    std::cout << "Filtered values: ";
    for (unsigned int i = 1; i <= 10; ++i) {
        // Skip numbers that are even and greater than 4
        if (i % 2 == 0 && i > 4) {
            continue; // skips printing, jumps to ++i
        }
        std::cout << i << " ";
    }
    std::cout << "\n";

    return 0;
}
